	requestedPort: number,
	owns: (port: number) => Promise<boolean> = async () => true,
): Promise<OpenPlan> {
	const requested = await resolvePortState(requestedPort);
	if (requested.lock) {
		const actualPort = await findAvailablePort(requestedPort + 1);
		return {
			requestedPort,
